def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    patterns = []
    source_cells = set()
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start > 1:
                seq = row[start:c]
                patterns.append(seq)
                source_cells.update((r, x) for x in range(start, c))
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in source_cells:
                continue
            for seq in patterns:
                if color in seq:
                    i = seq.index(color)
                    left = c - i
                    for j, value in enumerate(seq):
                        x = left + j
                        if 0 <= x < w:
                            out[r][x] = value
                    break
    return out
